    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    arr[i+1:] = arr[i+1:][::-1]
    return arr

def next_perm_expected(nums):
    # generate all unique permutations sorted lexicographically
    perms = sorted(set(itertools.permutations(nums)))
    try:
        idx = perms.index(tuple(nums))
    except ValueError:
        return None
    if idx == len(perms)-1:
        return list(sorted(nums))
    return list(perms[idx+1])

