import itertools, collections

def solve(nums):
    arr = list(nums)
    n = len(arr)
    if n <= 1:
        return arr
    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1
    if i == -1:
        return arr[::-1]
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    arr[i+1:] = arr[i+1:][::-1]
    return arr

def brute_next(nums):
    perms = sorted(set(itertools.permutations(nums)))
    idx = perms.index(tuple(nums))
    if idx == len(perms)-1:
        return list(perms[0])
    else:
        return list(perms[idx+1])

# test all multiset permutations for length up to 5 with values 0..2
for length in range(0,6):
    for nums in itertools.product([0,1,2], repeat=length):
        if solve(list(nums)) != brute_next(list(nums)):
            print('mismatch', nums, solve(list(nums)), brute_next(list(nums)))
            raise SystemExit
print('all match')

