def solve(grid):
    """Count islands (connected components of 1s) in a possibly ragged grid.
    Connectivity is 4-directional. Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                # iterative DFS
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    for nr, nc in neighbors(cr, cc):
                        if grid[nr][nc] == 1 and not visited[nr][nc]:
                            stack.append((nr, nc))
    return count

