def solve(grid):
    """Count islands in a possibly ragged grid.
    grid: list of lists containing 0 or 1. Rows may have different lengths.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1 and (ni, nj) not in visited:
                    stack.append((ni, nj))
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                count += 1
                dfs(r, c)
    return count

