def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles any iterable of integers; non-iterable inputs return 0.
    Uses patience sorting (O(n log n)) with bisect_left to maintain strictness.
    """
    # Convert to list safely
    try:
        seq = list(nums)
    except Exception:
        return 0
    if not seq:
        return 0
    import bisect
    tails = []  # tails[i] = smallest tail of an increasing subseq of length i+1
    for x in seq:
        # For strictly increasing, find first tail >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

