def solve(intervals):
    if not intervals:
        return []
    # Determine desired interval container type based on first element
    use_tuple = isinstance(intervals[0], tuple)
    # Sort intervals by start coordinate
    sorted_ints = sorted(intervals, key=lambda x: x[0])
    # Initialize first merged interval as mutable list
    first = list(sorted_ints[0])
    merged = [first]
    for start, end in sorted_ints[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    # Convert to original container type if needed
    if use_tuple:
        return [tuple(item) for item in merged]
    return merged

